import os
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("hotel-payments")
stripe.api_key = os.environ["STRIPE_SECRET_KEY"]

_ZERO_DECIMAL = {"jpy", "krw", "vnd", "clp"}


def _to_minor(amt, cur):
    if cur in _ZERO_DECIMAL:
        return int(round(amt))
    return int(round(amt * 100))


@mcp.tool()
def charge_hotel_deposit(
    customer_id: str,
    payment_method_id: str,
    reservation_ref: str,
    nightly_rate: float,
    nights: int,
    deposit_pct: float = 20.0,
    currency: str = "usd",
) -> dict:
    cur = currency.lower().strip()
    if len(cur) != 3:
        return {"ok": False, "error": "currency must be a 3-letter ISO code"}
    if nights < 1:
        return {"ok": False, "error": "nights must be at least 1"}
    if nightly_rate <= 0:
        return {"ok": False, "error": "nightly_rate must be positive"}
    if not 1 <= deposit_pct <= 100:
        return {"ok": False, "error": "deposit_pct must be between 1 and 100"}

    tot = nightly_rate * nights
    dep = tot * deposit_pct / 100.0
    amt = _to_minor(dep, cur)
    if amt < 50 and cur not in _ZERO_DECIMAL:
        return {"ok": False, "error": "deposit below minimum chargeable amount"}

    try:
        pi = stripe.PaymentIntent.create(
            amount=amt,
            currency=cur,
            customer=customer_id,
            payment_method=payment_method_id,
            off_session=True,
            confirm=True,
            description=f"Hotel deposit {reservation_ref}",
            metadata={"reservation_ref": reservation_ref, "nights": str(nights)},
            idempotency_key=f"hotel-dep-{reservation_ref}",
        )
    except stripe.error.CardError as e:
        return {"ok": False, "error": e.user_message or "card declined"}
    except stripe.error.StripeError as e:
        return {"ok": False, "error": str(e)}

    return {
        "ok": pi.status == "succeeded",
        "payment_intent_id": pi.id,
        "status": pi.status,
        "amount_charged": round(dep, 2),
        "currency": cur,
        "reservation_ref": reservation_ref,
    }

import os
import smtplib
from email.message import EmailMessage

import stripe
from agents import function_tool

stripe.api_key = os.environ["STRIPE_SECRET_KEY"]

_SMTP_HOST = os.environ.get("SMTP_HOST", "smtp.example-travel.com")
_SMTP_PORT = int(os.environ.get("SMTP_PORT", "587"))
_SMTP_USER = os.environ.get("SMTP_USER", "")
_SMTP_PASS = os.environ.get("SMTP_PASS", "")
_FROM_ADDR = os.environ.get("REFUNDS_FROM", "refunds@example-travel.com")
_VALID_REASONS = {"requested_by_customer", "duplicate", "fraudulent"}


def _build_message(to_addr, booking_ref, refund):
    msg = EmailMessage()
    msg["From"] = _FROM_ADDR
    msg["To"] = to_addr
    msg["Subject"] = f"Refund issued for booking {booking_ref}"
    amount = refund.amount / 100.0
    msg.set_content(
        f"Your refund for flight booking {booking_ref} has been issued.\n\n"
        f"Amount: {amount:.2f} {refund.currency.upper()}\n"
        f"Refund ID: {refund.id}\n"
        f"Status: {refund.status}\n\n"
        "Refunds typically appear on your statement within 5-10 business days."
    )
    return msg


@function_tool
def refund_flight_and_notify(
    payment_intent_id: str,
    booking_ref: str,
    traveler_email: str,
    amount_cents: int | None = None,
    reason: str = "requested_by_customer",
) -> dict:
    if reason not in _VALID_REASONS:
        return {"ok": False, "error": f"reason must be one of {sorted(_VALID_REASONS)}"}
    if amount_cents is not None and amount_cents <= 0:
        return {"ok": False, "error": "amount_cents must be positive"}

    params = {
        "payment_intent": payment_intent_id,
        "reason": reason,
        "metadata": {"booking_ref": booking_ref},
    }
    if amount_cents is not None:
        params["amount"] = amount_cents

    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.StripeError as exc:
        return {"ok": False, "error": str(exc)}

    msg = _build_message(traveler_email, booking_ref, refund)
    notified = True
    try:
        with smtplib.SMTP(_SMTP_HOST, _SMTP_PORT, timeout=20) as server:
            server.starttls()
            if _SMTP_USER:
                server.login(_SMTP_USER, _SMTP_PASS)
            server.send_message(msg)
    except (smtplib.SMTPException, OSError):
        notified = False

    return {
        "ok": True,
        "refund_id": refund.id,
        "status": refund.status,
        "amount_cents": refund.amount,
        "traveler_notified": notified,
    }
